mapper.insert:
INSERT INTO ultary_feed (
	user_no,
	content,
	visibility
) VALUES (
	#{userNo},
	#{content},
	#{visibility}
)

mapper.select:
SELECT COUNT(1)
FROM ultary_feed_pet fp
INNER JOIN ultary_pet p ON p.pet_id = fp.pet_id AND p.is_deleted = 0
WHERE fp.feed_id = #{feedId}
  AND fp.role = 'COLLABORATOR'
  AND p.user_no = #{userNo}

mapper.insert:
INSERT INTO ultary_feed_tag (
	feed_id,
	tag_id
) VALUES (
	#{feedId},
	#{tagId}
)

mapper.update:
UPDATE ultary_feed_like
SET is_deleted = 1,
	deleted_at = NOW()
WHERE feed_id = #{feedId}
  AND user_no = #{userNo}
  AND is_deleted = 0

UPDATE ultary_feed_store
SET is_deleted = 1,
	deleted_at = NOW()
WHERE feed_id = #{feedId}
  AND user_no = #{userNo}
  AND is_deleted = 0

mapper.insert:
INSERT INTO ultary_feed_comment (
	feed_id,
	user_no,
	content
) VALUES (
	#{feedId},
	#{userNo},
	#{content}
)

mapper.update:
UPDATE ultary_feed_comment
SET content = #{content},
	updated_at = NOW()
WHERE feed_comment_id = #{commentId}
  AND user_no = #{userNo}
  AND is_deleted = 0

UPDATE ultary_feed_comment
SET is_deleted = 1,
	deleted_at = NOW(),
	updated_at = NOW()
WHERE feed_comment_id = #{commentId}
  AND feed_id = #{feedId}
  AND is_deleted = 0
  AND EXISTS (
	SELECT 1
	FROM ultary_feed f
	WHERE f.feed_id = #{feedId}
	  AND f.user_no = #{feedAuthorUserNo}
	  AND f.is_deleted = 0
  )

mapper.insert:
INSERT INTO ultary_feed_reply (
	feed_comment_id,
	user_no,
	content
) VALUES (
	#{feedCommentId},
	#{userNo},
	#{content}
)

mapper.update:
UPDATE ultary_feed_reply
SET content = #{content},
	updated_at = NOW()
WHERE feed_reply_id = #{replyId}
  AND user_no = #{userNo}
  AND is_deleted = 0

UPDATE ultary_feed_reply
SET is_deleted = 1,
	deleted_at = NOW(),
	updated_at = NOW()
WHERE feed_reply_id = #{replyId}
  AND feed_comment_id = #{commentId}
  AND is_deleted = 0
  AND EXISTS (
	SELECT 1
	FROM ultary_feed_comment c
	INNER JOIN ultary_feed f ON f.feed_id = c.feed_id
	WHERE c.feed_comment_id = #{commentId}
	  AND f.user_no = #{feedAuthorUserNo}
	  AND f.is_deleted = 0
  )
